#include <stdio.h>
#include <string.h>

typedef enum { INT, STRING } FieldType;

typedef struct { char name[32]; FieldType type; int min; int max; } FieldRule;
typedef struct { char name[32]; FieldType type; int int_val; char str_val[64]; } Field;

int validate(FieldRule *rules, Field *fields, int count) {
    for (int i = 0; i < count; i++) {
        int ok = 1;
        if (fields[i].type == INT)
            ok = fields[i].int_val >= rules[i].min && fields[i].int_val <= rules[i].max;
        else if (fields[i].type == STRING) {
            int len = strlen(fields[i].str_val);
            ok = len >= rules[i].min && len <= rules[i].max;
        }
        printf("%s: %s\n", fields[i].name, ok ? "OK" : "INVALID");
    }
    return 0;
}

int main() {
    FieldRule rules[2] = {{"age", INT, 0, 150}, {"name", STRING, 1, 50}};
    Field fields[2] = {{"age", INT, .int_val=25}, {"name", STRING, .str_val="Alice"}};
    validate(rules, fields, 2);
    fields[0].int_val = -5;
    validate(rules, fields, 2);
    return 0;
}
